static Rational rationalCandidate(double v){int64_t n,d;return fractionValue(v,&n,&d)?rat(n,d):(Rational){0,0};}
static int exactEquation84(const char*eq,Rational vars[3]){char raw[2048],expanded[8192];const char*equal=strchr(eq,'=');if(equal)snprintf(raw,sizeof(raw),"(%.*s)-(%s)",(int)(equal-eq),eq,equal+1);else snprintf(raw,sizeof(raw),"%s",eq);size_t used=0;for(const char*p=raw;*p;){if(isalpha((unsigned char)*p)){const char*start=p;while(isalpha((unsigned char)*p))p++;if(p-start==1&&strchr("xXyYzZ",*start)){int j=tolower((unsigned char)*start)-'x';if(!vars[j].d)return 0;int n=snprintf(expanded+used,sizeof(expanded)-used,"(%lld/%lld)",(long long)vars[j].n,(long long)vars[j].d);if(n<0||(size_t)n>=sizeof(expanded)-used)return 0;used+=n;}else{size_t n=p-start;if(used+n>=sizeof(expanded))return 0;memcpy(expanded+used,start,n);used+=n;}}else{if(used+1>=sizeof(expanded))return 0;expanded[used++]=*p++;}}expanded[used]=0;Rational result=exactExpression(expanded,exactAns);return result.d&&result.n==0;}
static void rootNumberText(double value,char*out,size_t size){Rational r=rationalCandidate(value);int proven=0;if(r.d&&solverKind==0){Rational v=rat(0,1);for(int i=0;i<=polyDegree;i++)v=rop(rop(v,r,'*'),exactExpression(solverFields[0][i],exactAns),'+');proven=v.d&&v.n==0;}else if(r.d&&solverKind==1){Rational vars[3]={r,{0,0},{0,0}};proven=exactEquation84(solverFields[1][0],vars);}exactNumberText(value,proven?r:(Rational){0,0},out,size);}
static void systemNumberText(int index,char*out,size_t size){int n=solverKind==2?solverN:2;Rational vars[3]={{0,0},{0,0},{0,0}};int proven=1;for(int j=0;j<n;j++){vars[j]=rationalCandidate(systemSolution[j]);if(!vars[j].d)proven=0;}for(int j=0;j<n&&proven;j++)proven=exactEquation84(solverFields[solverKind][j],vars);exactNumberText(systemSolution[index],proven?vars[index]:(Rational){0,0},out,size);}
